class Bucket:
    def __init__(self, rate, burst):
        self.rate = rate
        self.burst = burst
        self.tokens = burst
        self.last = 0.0

    def allow(self, now, cost=1):
        self.tokens += (now - self.last) * self.rate
        if self.tokens > self.burst:
            self.tokens = self.burst
        self.last = now
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False
